package com.obysoft.faithOS.entity;
import java.time.*;import jakarta.persistence.*;
@Entity @Table(name="absence_motivations") public class AbsenceMotivation{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Church church;@ManyToOne(optional=false)private User user;@Column(name="absence_date",nullable=false)private LocalDate absenceDate;@Column(nullable=false,columnDefinition="text")private String reason;@Column(nullable=false)private String status="SUBMITTED";@Column(name="created_at",nullable=false)private LocalDateTime createdAt;@Column(name="reviewed_at")private LocalDateTime reviewedAt;@Column(name="expires_at")private LocalDateTime expiresAt;@ManyToOne @JoinColumn(name="reviewed_by_id")private User reviewedBy;@PrePersist void before(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;}public Church getChurch(){return church;}public void setChurch(Church v){church=v;}public User getUser(){return user;}public void setUser(User v){user=v;}public LocalDate getAbsenceDate(){return absenceDate;}public void setAbsenceDate(LocalDate v){absenceDate=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getReviewedAt(){return reviewedAt;}public void setReviewedAt(LocalDateTime v){reviewedAt=v;}public LocalDateTime getExpiresAt(){return expiresAt;}public void setExpiresAt(LocalDateTime v){expiresAt=v;}public User getReviewedBy(){return reviewedBy;}public void setReviewedBy(User v){reviewedBy=v;}
}
